from pathlib import Path
import re


def replace_once(text: str, pattern: str, replacement: str, name: str) -> str:
    updated, count = re.subn(pattern, replacement, text, count=1, flags=re.S)
    if count != 1:
        raise RuntimeError(f'Expected exactly one {name} block, found {count}')
    return updated


# Accounting: the controller already owns the canonical UnifiedQuery state and
# exposes visibleEntries. Remove the page-local search/currency state and bind
# the UI directly to the same controller/query used by the filter engine.
p = Path('lib/features/accounting/pages/accounting_page.dart')
s = p.read_text(encoding='utf-8')
s = s.replace(
    "import 'package:quality_line_erp/core/localization/app_localizations.dart';\n",
    "import 'package:quality_line_erp/core/localization/app_localizations.dart';\nimport 'package:quality_line_erp/core/filtering/unified_query.dart';\nimport 'package:quality_line_erp/design_system/kaj_query_toolbar.dart';\n",
    1,
)
s = s.replace("  final _searchController = TextEditingController();\n  String _currencyFilter = 'ALL';\n", '', 1)
s = s.replace("\n  @override\n  void dispose() {\n    _searchController.dispose();\n    super.dispose();\n  }\n", '\n', 1)
s = replace_once(
    s,
    r"                  Row\(\n                    children: \[\n                      Expanded\(\n                        child: TextField\(\n                          controller: _searchController,.*?                  const SizedBox\(height: 16\),\n                  if \(controller\.errorMessage != null\)",
    """                  Column(\n                    crossAxisAlignment: CrossAxisAlignment.stretch,\n                    children: [\n                      KajQueryToolbar(\n                        controller: controller.query,\n                        hintText: AppTranslation.translate('البحث في القيود'),\n                        filters: [\n                          UnifiedQueryFilterOption(\n                            token: UnifiedFilterToken(\n                              key: 'currency',\n                              label: AppTranslation.translate('العملة'),\n                              value: 'IQD',\n                              valueLabel: 'IQD',\n                            ),\n                            icon: Icons.payments_outlined,\n                          ),\n                          UnifiedQueryFilterOption(\n                            token: UnifiedFilterToken(\n                              key: 'currency',\n                              label: AppTranslation.translate('العملة'),\n                              value: 'USD',\n                              valueLabel: 'USD',\n                            ),\n                            icon: Icons.payments_outlined,\n                          ),\n                        ],\n                        sorts: [\n                          UnifiedQuerySortOption(\n                            rule: UnifiedSortRule(\n                              field: 'entryDate',\n                              label: AppTranslation.translate('تاريخ القيد'),\n                            ),\n                            icon: Icons.event_outlined,\n                          ),\n                          UnifiedQuerySortOption(\n                            rule: UnifiedSortRule(\n                              field: 'entryNumber',\n                              label: AppTranslation.translate('رقم القيد'),\n                            ),\n                            icon: Icons.tag_outlined,\n                          ),\n                          UnifiedQuerySortOption(\n                            rule: UnifiedSortRule(\n                              field: 'totalDebit',\n                              label: AppTranslation.translate('إجمالي المدين'),\n                            ),\n                            icon: Icons.account_balance_wallet_outlined,\n                          ),\n                          UnifiedQuerySortOption(\n                            rule: UnifiedSortRule(\n                              field: 'currency',\n                              label: AppTranslation.translate('العملة'),\n                            ),\n                            icon: Icons.payments_outlined,\n                          ),\n                        ],\n                        compact: true,\n                        filterButtonLabel: AppTranslation.translate('فلترة'),\n                        sortButtonLabel: AppTranslation.translate('فرز'),\n                        clearAllLabel: AppTranslation.translate('مسح الكل'),\n                        clearSearchTooltip: AppTranslation.translate('مسح البحث'),\n                        ascendingLabel: AppTranslation.translate('تصاعدي'),\n                        descendingLabel: AppTranslation.translate('تنازلي'),\n                      ),\n                      const SizedBox(height: 8),\n                      FilledButton.tonalIcon(\n                        onPressed: _openAdd,\n                        icon: const Icon(Icons.add_rounded, size: 18),\n                        label: const AppText('قيد جديد'),\n                      ),\n                    ],\n                  ),\n                  const SizedBox(height: 16),\n                  if (controller.errorMessage != null)""",
    'accounting legacy toolbar',
)
s = replace_once(
    s,
    r"                  Builder\(\n                    builder: \(context\) \{\n                      final query = _searchController\.text\.trim\(\)\.toLowerCase\(\);.*?                    \},\n                  \),",
    """                  Builder(\n                    builder: (context) {\n                      final entries = controller.visibleEntries;\n                      if (entries.isEmpty) {\n                        return const Padding(\n                          padding: EdgeInsets.all(50),\n                          child: Center(child: AppText('لا توجد قيود مطابقة.')),\n                        );\n                      }\n                      return Column(\n                        children: entries\n                            .map(\n                              (entry) => _entryCard(context, controller, entry),\n                            )\n                            .toList(growable: false),\n                      );\n                    },\n                  ),""",
    'accounting local filtering',
)
p.write_text(s, encoding='utf-8')

# Inventory: search and group selection become unified query state. Warehouse
# remains an explicit cloud data scope because it changes the repository query.
p = Path('lib/features/inventory/pages/inventory_page.dart')
s = p.read_text(encoding='utf-8')
s = s.replace(
    "import 'package:quality_line_erp/core/localization/app_localizations.dart';\n",
    "import 'package:quality_line_erp/core/localization/app_localizations.dart';\nimport 'package:quality_line_erp/core/filtering/unified_query.dart';\nimport 'package:quality_line_erp/design_system/kaj_query_toolbar.dart';\n",
    1,
)
start = s.index('  Widget _filters(InventoryController controller) {')
end = s.index('\n  Widget _emptyState() {', start)
new_filters = """  Widget _filters(InventoryController controller) {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final compact = constraints.maxWidth < 760;\n        final queryToolbar = KajQueryToolbar(\n          controller: controller.query,\n          hintText: AppTranslation.translate(\n            'بحث باسم المنتج أو الرمز أو الباركود...',\n          ),\n          filters: [\n            for (final item in controller.groups)\n              UnifiedQueryFilterOption(\n                token: UnifiedFilterToken(\n                  key: 'inventory.group',\n                  label: AppTranslation.translate('المجموعة'),\n                  value: item.id,\n                  valueLabel: item.name,\n                ),\n                icon: Icons.category_outlined,\n              ),\n          ],\n          sorts: [\n            UnifiedQuerySortOption(\n              rule: UnifiedSortRule(\n                field: 'name',\n                label: AppTranslation.translate('اسم المنتج'),\n              ),\n              icon: Icons.sort_by_alpha_outlined,\n            ),\n            UnifiedQuerySortOption(\n              rule: UnifiedSortRule(\n                field: 'quantity',\n                label: AppTranslation.translate('الكمية'),\n              ),\n              icon: Icons.inventory_2_outlined,\n            ),\n            UnifiedQuerySortOption(\n              rule: UnifiedSortRule(\n                field: 'availableQuantity',\n                label: AppTranslation.translate('المتاح'),\n              ),\n              icon: Icons.check_circle_outline,\n            ),\n            UnifiedQuerySortOption(\n              rule: UnifiedSortRule(\n                field: 'expectedQuantity',\n                label: AppTranslation.translate('الرصيد المتوقع'),\n              ),\n              icon: Icons.insights_outlined,\n            ),\n            UnifiedQuerySortOption(\n              rule: UnifiedSortRule(\n                field: 'unitCost',\n                label: AppTranslation.translate('الكلفة'),\n              ),\n              icon: Icons.payments_outlined,\n            ),\n          ],\n          compact: true,\n          filterButtonLabel: AppTranslation.translate('فلترة'),\n          sortButtonLabel: AppTranslation.translate('فرز'),\n          clearAllLabel: AppTranslation.translate('مسح الكل'),\n          clearSearchTooltip: AppTranslation.translate('مسح البحث'),\n          ascendingLabel: AppTranslation.translate('تصاعدي'),\n          descendingLabel: AppTranslation.translate('تنازلي'),\n        );\n        final warehouse = DropdownButtonFormField<String>(\n          isExpanded: true,\n          initialValue: controller.selectedWarehouseId ?? '__all__',\n          decoration: InputDecoration(\n            labelText: AppTranslation.translate('المخزن'),\n          ),\n          items: [\n            DropdownMenuItem<String>(\n              value: '__all__',\n              child: AppText(\n                context.l10n.isArabic ? 'جميع المخازن' : 'All warehouses',\n              ),\n            ),\n            ...controller.warehouses.map(\n              (item) => DropdownMenuItem<String>(\n                value: item.id,\n                child: AppText(item.name),\n              ),\n            ),\n          ],\n          onChanged: (value) =>\n              controller.setWarehouseFilter(value == '__all__' ? null : value),\n        );\n        if (compact) {\n          return Column(\n            crossAxisAlignment: CrossAxisAlignment.stretch,\n            children: [\n              queryToolbar,\n              const SizedBox(height: 8),\n              warehouse,\n            ],\n          );\n        }\n        return Row(\n          children: [\n            Expanded(child: queryToolbar),\n            const SizedBox(width: 8),\n            SizedBox(width: 210, child: warehouse),\n          ],\n        );\n      },\n    );\n  }\n"""
s = s[:start] + new_filters + s[end:]
p.write_text(s, encoding='utf-8')

# Inventory controller: remove the compatibility accessors/wrappers now that
# the only UI caller has been migrated to query directly.
p = Path('lib/features/inventory/controllers/inventory_controller.dart')
s = p.read_text(encoding='utf-8')
s = s.replace("""  /// Compatibility accessors retained while existing pages migrate to [query].\n  /// They contain no independent query state.\n  String get searchQuery => query.state.search;\n  String? get selectedGroupId => _groupFilterValue;\n\n""", '', 1)
s = s.replace("""  @Deprecated('Use query.setSearch()')\n  void setSearchQuery(String value) => query.setSearch(value);\n\n  @Deprecated('Use query.addFilter()')\n  void setGroupFilter(String? value) {\n    if (value == null || value.isEmpty) {\n      query.removeFilterKey('inventory.group');\n      return;\n    }\n    var label = value;\n    for (final group in _groups) {\n      if (group.id == value) {\n        label = group.name;\n        break;\n      }\n    }\n    query.addFilter(\n      UnifiedFilterToken(\n        key: 'inventory.group',\n        label: 'Group',\n        value: value,\n        valueLabel: label,\n      ),\n    );\n  }\n\n""", '', 1)
p.write_text(s, encoding='utf-8')

print('Phase 4 unified query cleanup applied.')
